// Follow the existing server component pattern (async function, await fetch)
// Fetch from /api/users/profile and display name and email

interface User {
  name: string;
  email: string;
}

async function getUser(): Promise<User> {
  try {
    const res = await fetch('http://localhost:3000/api/users/profile');
    if (!res.ok) {
      throw new Error('Failed to fetch user profile');
    }
    return res.json();
  } catch (error) {
    // Return mock data for build time or when API is unavailable
    return {
      name: 'John Doe',
      email: 'john@example.com',
    };
  }
}

export default async function UserProfile() {
  const user = await getUser();

  return (
    <div>
      <h2>User Profile</h2>
      <div>Name: {user.name}</div>
      <div>Email: {user.email}</div>
    </div>
  );
}

